import itertools
from collections import Counter

def count_digit_appearances(year, month, day):
    year_str = str(year)
    month_str = str(month)
    day_str = str(day)

    year_counter = Counter(year_str)
    month_counter = Counter(month_str)
    day_counter = Counter(day_str)

    total_counter = Counter()
    for year_digit, month_digit, day_digit in itertools.product(year_counter.keys(), month_counter.keys(), day_counter.keys()):
        total_counter[year_digit] += year_counter[year_digit]
        total_counter[month_digit] += month_counter[month_digit]
        total_counter[day_digit] += day_counter[day_digit]

    return total_counter

def count_even_digit_appearances(year, month, day):
    counter = count_digit_appearances(year, month, day)
    return all(count % 2 == 0 for count in counter.values())

def count_valid_dates():
    valid_dates = 0
    for year in range(2023):
        for month in range(1, 13):
            for day in range(1, 32):
                if count_even_digit_appearances(year, month, day):
                    valid_dates += 1
    return valid_dates

print(count_valid_dates())

